69	function lathe(points: [number, number][], segs: number, v0: number, v1: number): THREE.LatheGeometry {
70	  const g = new THREE.LatheGeometry(points.map(([r, y]) => new THREE.Vector2(r, y)), segs);
71	  const p = g.attributes.position as THREE.BufferAttribute;
72	  const uv = g.attributes.uv as THREE.BufferAttribute;
73	  for (let i = 0; i < p.count; i++) uv.setXY(i, uv.getX(i), (p.getY(i) - v0) / (v1 - v0));
74	  return g;
75	}
