77	/** the GLB's beanie profiles (build.ts) with the HAT05 cuff height; u = once around (+Z front = 0, back = 0.5) */
78	function hatGeometries(cuffH: number, taper: number, crownH: number): { brim: THREE.BufferGeometry; crown: THREE.BufferGeometry; yt: number; crownTop: number } {
79	  const yb = D.brimBottom;
80	  const yt = yb + cuffH;
81	  const bk = D.brimR / 0.778;
82	  const bw = bk * HAT05.brimW;
83	  const lip = Math.sqrt(D.skin * D.skin - yb * yb) + 0.012;
84	  const brim = lathe(
85	    [
86	      [lip, yb + 0.01],
87	      [0.725 * bw, yb - 0.008],
88	      [0.758 * bw, yb + 0.02],
89	      [0.776 * bw, yb + 0.07],
90	      [0.781 * bw, yb + 0.5 * cuffH],
91	      // fuller rolled top edge (approved: the cuff's upper corners stand higher at the sides)
92	      [0.781 * bw, yt - 0.06],
93	      [0.772 * bw, yt - 0.022],
94	      [0.745 * bw, yt - 0.004],
95	      [0.69 * bk, yt],
96	    ],
97	    96,
98	    yb - 0.01,
99	    yt + 0.005,
100	  );
101	  const crownY0 = yt - 0.045;
102	  const R0 = 0.705 * bk;
103	  const prof: [number, number][] = [];
104	  for (const t of [0, 0.08, 0.16, 0.25, 0.34, 0.43, 0.52, 0.6, 0.68, 0.75, 0.81, 0.86, 0.9, 0.935, 0.96, 0.98, 0.993, 1]) {
105	    prof.push([R0 * Math.sqrt(Math.max(0, 1 - t * t)) * (1 - taper * t), crownY0 + t * crownH]);
106	  }
107	  const crown = lathe(prof, 96, crownY0, crownY0 + crownH);
108	  return { brim, crown, yt, crownTop: crownY0 + crownH };
109	}
