111	/** a copy of the swim clip whose body side roll is scaled by ROLL05 (the cached GLB clips stay untouched) */
112	export function dampedClips(clips: THREE.AnimationClip[]): THREE.AnimationClip[] {
113	  return clips.map((c) => {
114	    if (c.name !== 'swim') return c;
115	    const k = c.clone();
116	    for (const t of k.tracks) {
117	      if (t.name !== 'body.quaternion') continue;
118	      const q = new THREE.Quaternion(), e = new THREE.Euler();
119	      for (let i = 0; i < t.values.length; i += 4) {
120	        q.fromArray(t.values, i);
121	        e.setFromQuaternion(q, 'XYZ');
122	        e.z *= ROLL05;
123	        q.setFromEuler(e).toArray(t.values, i);
124	      }
125	    }
126	    return k;
127	  });
