144	let loaded: Promise<Record<string, THREE.Texture | null>> | null = null;
145	/** load every baked map once (missing files → null: that part keeps its GLB look) */
146	export function loadBenny05Maps(): Promise<Record<string, THREE.Texture | null>> {
147	  if (loaded) return loaded;
