182	/**
183	 * Apply the corrected look to a freshly cloned Benny scene (after the fur upgrade). `maps` from loadBenny05Maps().
184	 */
185	export function applyBenny05(scene: THREE.Object3D, furs: FurHandle[], maps: Record<string, THREE.Texture | null>): Benny05Handle {
186	  const get = (n: string) => scene.getObjectByName(n);
187	  // ---- beanie geometry ----
188	  const hat = get('hat')!;
189	  hat.position.y -= HAT05.drop;
190	  hat.position.x += HAT05.shiftX;
191	  hat.rotation.x += HAT05.tilt;
192	  const g = hatGeometries(HAT05.cuffH, HAT05.crownTaper, HAT05.crownH);
193	  const brim = get('hat_brim') as THREE.Mesh;
194	  const crown = get('hat_crown') as THREE.Mesh;
195	  brim.geometry = g.brim;
196	  crown.geometry = g.crown;
197	  const dCuff = HAT05.cuffH - D.cuffH;
198	  const star = get('hat_star') as THREE.Mesh;
199	  star.position.y += dCuff + HAT05.starDY;
200	  star.position.x += HAT05.starDX;
201	  star.scale.set(HAT05.starScale[0], HAT05.starScale[1], 1);
202	  const pom = get('pom')!;
203	  pom.position.y += dCuff + (HAT05.crownH - D.crownH) + HAT05.pomDY;
204	  pom.position.x += HAT05.pomDX;
205	  pom.position.z += HAT05.pomDZ;
206	  pom.scale.setScalar(HAT05.pomScale);
207	
208	  // ---- fur clumping ----
209	  for (const f of furs) {
210	    const c = CLUMP05[f.mesh.name];
211	    if (c !== undefined) f.uniforms.uClump.value = c;
212	  }
213	
214	  // ---- materials (own copies: the cached GLB materials are shared by every clone) ----
215	  const white = new THREE.DataTexture(new Uint8Array([255, 255, 255, 255]), 1, 1);
216	  white.needsUpdate = true;
217	  type St = { mesh: THREE.Mesh; mat: THREE.MeshStandardMaterial; map: THREE.Texture | null; color: THREE.Color; fur?: FurHandle; root?: THREE.Color; tip?: THREE.Color };
218	  const baked: St[] = [];
219	  scene.traverse((o) => {
220	    const m = o as THREE.Mesh;
221	    if (!m.isMesh) return;
222	    const spec = MAPS05[m.name];
223	    if (!spec) return;
224	    const fur = furs.find((f) => f.mesh === m);
225	    const mat = fur ? fur.material : (m.material as THREE.MeshStandardMaterial).clone();
226	    if (!fur) m.material = mat;
227	    const tex = maps[spec.map];
228	    if (fur) {
229	      const d = mat.defines ?? (mat.defines = {});
230	      d.BENNY05 = '';
231	    }
232	    if (tex) {
233	      if (fur) {
234	        // root → tip shading only as a relative factor on the baked colour
235	        fur.uniforms.uRoot.value.setRGB(0.86, 0.86, 0.86);
236	        fur.uniforms.uTip.value.setRGB(1, 1, 1);
237	      }
238	      mat.map = tex;
239	      mat.color.setScalar(spec.scale);
240	      if (!fur) {
241	        const n = spec.normal ? maps[spec.normal] : null;
242	        mat.normalMap = n;
243	        if (n) mat.normalScale.setScalar(spec.normalScale ?? 1);
244	      }
245	    } else if (fur) {
246	      // no bake yet: keep the GLB root / tip colours through the multiply path
247	      mat.map = white;
248	    } else if (m.name === 'hat_crown' && mat.map) {
249	      mat.map = mat.map.clone();
250	      mat.map.repeat.x = 4; // GLB crown texture was authored for a 4× u repeat
251	      mat.map.needsUpdate = true;
252	      if (mat.normalMap) { mat.normalMap = mat.normalMap.clone(); mat.normalMap.repeat.x = 4; mat.normalMap.needsUpdate = true; }
253	    }
254	    mat.needsUpdate = true;
255	    baked.push({ mesh: m, mat, map: mat.map, color: mat.color.clone(), fur, root: fur?.uniforms.uRoot.value.clone(), tip: fur?.uniforms.uTip.value.clone() });
256	  });
257	  const starMat = (star.material as THREE.MeshStandardMaterial).clone();
258	  starMat.color.setRGB(...STAR05.color);
259	  star.material = starMat;
260	  const starCol = starMat.color.clone();
261	
262	  // ---- QA hooks ----
263	  const uvPass: Benny05Handle['uvPass'] = (renderer, world, camera, rect) => {
264	    const size = renderer.getDrawingBufferSize(new THREE.Vector2());
265	    const rt = new THREE.WebGLRenderTarget(size.x, size.y, { type: THREE.FloatType, depthBuffer: true });
266	    const root = scene.parent!;
267	    const vis: [THREE.Object3D, boolean][] = [];
268	    for (const c of world.children) { vis.push([c, c.visible]); if (c !== root) c.visible = false; }
269	    const bg = world.background;
270	    world.background = null;
271	    const saved: [THREE.Mesh, THREE.Material | THREE.Material[]][] = [];
272	    const tmp: THREE.Material[] = [];
273	    scene.traverse((o) => {
274	      const m = o as THREE.Mesh;
275	      if (!m.isMesh) return;
276	      const id = partId(m.name);
277	      const fur = furs.find((f) => f.mesh === m);
278	      if (fur) {
279	        const d = fur.material.defines ?? (fur.material.defines = {});
280	        if (d.BENNY05 === undefined) { d.BENNY05 = ''; d.B05_TMP = ''; }
281	        d.BENNY_UV = '';
282	        fur.uniforms.uMaskCol.value.setRGB(id, 0, 0);
283	        fur.material.needsUpdate = true;
284	        return;
285	      }
286	      saved.push([m, m.material]);
287	      const side = (m.material as THREE.Material).side;
288	      const sm = new THREE.ShaderMaterial({
289	        uniforms: { uId: { value: id } },
290	        vertexShader: 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
291	        fragmentShader: 'uniform float uId; varying vec2 vUv; void main(){ gl_FragColor = vec4(vUv, uId, 0.0); }',
292	        side,
293	      });
294	      tmp.push(sm);
295	      m.material = sm;
296	    });
297	    const prevTarget = renderer.getRenderTarget();
298	    const prevClear = renderer.getClearColor(new THREE.Color());
299	    const prevAlpha = renderer.getClearAlpha();
300	    renderer.setRenderTarget(rt);
301	    renderer.setClearColor(0x000000, 0);
302	    renderer.clear();
303	    renderer.render(world, camera);
304	    const [x, y, w, h] = rect;
305	    const buf = new Float32Array(w * h * 4);
306	    renderer.readRenderTargetPixels(rt, x, size.y - y - h, w, h, buf);
307	    renderer.setRenderTarget(prevTarget);
308	    renderer.setClearColor(prevClear, prevAlpha);
309	    for (const [m, mat] of saved) m.material = mat;
310	    for (const t of tmp) t.dispose();
311	    for (const f of furs) {
312	      const d = f.material.defines;
313	      if (d?.BENNY_UV !== undefined) { delete d.BENNY_UV; f.material.needsUpdate = true; }
314	      if (d?.B05_TMP !== undefined) { delete d.B05_TMP; delete d.BENNY05; }
315	    }
316	    for (const [c, v] of vis) c.visible = v;
317	    world.background = bg;
318	    rt.dispose();
319	    const bytes = new Uint8Array(buf.buffer);
320	    let s = '';
321	    for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
322	    return btoa(s);
323	  };
324	  const calib: Benny05Handle['calib'] = (k) => {
325	    for (const b of baked) {
326	      b.mat.map = k === null ? b.map : white;
327	      if (k === null) b.mat.color.copy(b.color); else b.mat.color.setScalar(k);
328	      if (b.fur) {
329	        // calibration always sees the baked-mode relative root → tip factor
330	        if (k === null) { b.fur.uniforms.uRoot.value.copy(b.root!); b.fur.uniforms.uTip.value.copy(b.tip!); }
331	        else { b.fur.uniforms.uRoot.value.setRGB(0.86, 0.86, 0.86); b.fur.uniforms.uTip.value.setRGB(1, 1, 1); }
332	      }
333	      b.mat.needsUpdate = true;
334	    }
335	    if (k === null) starMat.color.copy(starCol); else starMat.color.setScalar(k);
336	  };
337	  return { uvPass, calib };
338	}
