2	 * Real-time shell-texturing fur for Benny (mobile-safe, one draw call per furry part).
3	 *
4	 * Each fur_* mesh becomes an InstancedMesh with `shells` instances; gl_InstanceID selects the
5	 * shell layer, which is pushed out along the normal (plus a little gravity droop). A hashed 3-D
6	 * strand grid decides per-fragment whether a strand still exists at that height (tapering strands),
7	 * so the fur keeps a fluffy silhouette from every angle. Built on MeshStandardMaterial via
8	 * onBeforeCompile so scene lighting, IBL and fog all still apply.
9	 */
10	import * as THREE from 'three';
11	
12	export interface FurParams {
13	  length: number;
14	  density: number;
15	  shells: number;
16	  root: string;
17	  tip: string;
18	  gravity?: number;
19	  bald?: [number, number, number, number];
20	  short?: [number, number, number, number, number, number];
21	}
22	
23	export interface FurHandle {
24	  mesh: THREE.InstancedMesh;
25	  material: THREE.MeshStandardMaterial;
26	  uniforms: {
27	    uTime: { value: number };
28	    uWind: { value: THREE.Vector3 };
29	    uMaskCol: { value: THREE.Color };
30	    uRoot: { value: THREE.Color };
31	    uTip: { value: THREE.Color };
32	    uClump: { value: number };
33	  };
34	}
35	
36	export function makeFur(src: THREE.Mesh, p: FurParams): FurHandle {
37	  const shells = Math.max(2, Math.round(p.shells));
38	  const uniforms = {
39	    uFurLen: { value: p.length },
40	    uDensity: { value: p.density },
41	    uRoot: { value: new THREE.Color(p.root) },
42	    uTip: { value: new THREE.Color(p.tip) },
43	    uGravity: { value: p.gravity ?? 0.3 },
44	    uBald: { value: new THREE.Vector4(...(p.bald ?? [0, 1, 0, 2])) },
45	    uShortDir: { value: new THREE.Vector3(...((p.short?.slice(0, 3) as [number, number, number]) ?? [0, 0, 1])) },
46	    uShort: { value: new THREE.Vector3(p.short?.[3] ?? 2, p.short?.[4] ?? 3, p.short?.[5] ?? 1) },
47	    uTime: { value: 0 },
48	    uWind: { value: new THREE.Vector3() },
49	    /** QA segmentation colour (only compiled in when material.defines.BENNY_MASK is set, see runtime.ts) */
50	    uMaskCol: { value: new THREE.Color(1, 0, 0) },
51	    /** `?benny05=1` only (material.defines.BENNY05, benny05.ts): strand clumping toward tuft centres */
52	    uClump: { value: 0.42 },
53	  };
54	  const material = new THREE.MeshStandardMaterial({ color: '#ffffff', roughness: 0.9, metalness: 0 });
55	  material.onBeforeCompile = (shader) => {
56	    Object.assign(shader.uniforms, uniforms);
57	    shader.vertexShader = shader.vertexShader
58	      .replace(
59	        '#include <common>',
60	        `#include <common>
61	        uniform float uFurLen; uniform float uGravity; uniform vec4 uBald;
62	        uniform vec3 uShortDir; uniform vec3 uShort; uniform float uTime; uniform vec3 uWind;
63	        varying float vLayer; varying vec3 vBase; varying float vLenMask;
64	        #ifdef BENNY05
65	        varying vec2 vB05Uv;
66	        #endif`,
67	      )
68	      .replace(
69	        '#include <begin_vertex>',
70	        `#include <begin_vertex>
71	        vLayer = float(gl_InstanceID) / float(${shells - 1});
72	        vec3 nrm = normalize(objectNormal);
73	        float bald = 1.0 - smoothstep(uBald.w - 0.04, uBald.w + 0.01, dot(nrm, normalize(uBald.xyz)));
74	        float sh = mix(1.0, uShort.z, smoothstep(uShort.x, uShort.y, dot(nrm, normalize(uShortDir))));
75	        vLenMask = bald * sh;
76	        vBase = position;
77	        #ifdef BENNY05
78	        vB05Uv = uv;
79	        #endif
80	        float h = uFurLen * vLayer * vLenMask;
81	        transformed += nrm * h;
82	        // gravity droop + gentle wind sway grows with layer height
83	        vec3 g = vec3(0.0, -1.0, 0.0) * uGravity + uWind;
84	        g += vec3(sin(uTime * 3.0 + position.y * 9.0), 0.0, cos(uTime * 2.3 + position.x * 7.0)) * 0.06;
85	        transformed += g * uFurLen * vLayer * vLayer * vLenMask;`,
86	      );
87	    shader.fragmentShader = shader.fragmentShader
88	      .replace(
89	        '#include <common>',
90	        `#include <common>
91	        uniform float uDensity; uniform vec3 uRoot; uniform vec3 uTip;
92	        varying float vLayer; varying vec3 vBase; varying float vLenMask;
93	        #ifdef BENNY05
94	        varying vec2 vB05Uv;
95	        uniform float uClump;
96	        #endif
97	        float fhash(vec3 p) { p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
98	        vec3 fhash3(vec3 p) { return vec3(fhash(p), fhash(p + 17.31), fhash(p + 41.7)); }`,
99	      )
100	      .replace(
101	        '#include <color_fragment>',
102	        `#include <color_fragment>
103	        {
104	          vec3 q = vBase * uDensity;
105	          // clumping: strands lean toward low-frequency tuft centres as they rise → plush tufts
106	          vec3 qc = q * 0.2;
107	          vec3 cc = (floor(qc) + 0.5 + (fhash3(floor(qc)) - 0.5) * 0.7) / 0.2;
108	          #ifdef BENNY05
109	          q = mix(q, cc, vLayer * uClump);
110	          #else
111	          q = mix(q, cc, vLayer * 0.42);
112	          #endif
113	          vec3 cell = floor(q);
114	          float best = 10.0; float hgt = 0.0;
115	          // nearest strand among this + neighbouring cells (gives round, jittered strands)
116	          for (int k = 0; k < 8; k++) {
117	            vec3 o = vec3(float(k & 1), float((k >> 1) & 1), float((k >> 2) & 1));
118	            vec3 c = floor(q - 0.5) + o;
119	            vec3 jp = c + 0.5 + (fhash3(c) - 0.5) * 0.8;
120	            float d = length(q - jp);
121	            if (d < best) { best = d; hgt = fhash(c * 1.7 + 3.1); }
122	          }
123	          float layer = vLayer;
124	          if (layer > 0.001) {
125	            if (vLenMask < 0.05) discard;
126	            float strandH = 0.55 + 0.45 * hgt;
127	            float radius = 0.78 * (1.0 - 0.85 * layer / strandH);
128	            if (layer > strandH || best > radius) discard;
129	          }
130	          float ao = mix(0.55, 1.0, smoothstep(0.0, 0.9, layer));
131	          #ifdef BENNY05
132	          // benny05.ts: colour = material colour x baked albedo map (map_fragment above); the shells only add the
133	          // root-to-tip occlusion and the per-strand variation on top of it
134	          diffuseColor.rgb *= mix(uRoot, uTip, smoothstep(0.0, 1.0, layer)) * ao * (0.92 + 0.16 * hgt);
135	          #else
136	          diffuseColor.rgb = mix(uRoot, uTip, smoothstep(0.0, 1.0, layer)) * ao * (0.92 + 0.16 * hgt);
137	          #endif
138	        }`,
139	      )
140	      .replace(
141	        '#include <emissivemap_fragment>',
142	        `#include <emissivemap_fragment>
143	        totalEmissiveRadiance += diffuseColor.rgb * 0.10 * vLayer;`,
144	      )
145	      .replace(
146	        '#include <dithering_fragment>',
147	        `#include <dithering_fragment>
148	        #ifdef BENNY_MASK
149	        gl_FragColor = vec4(uMaskCol, 1.0);
150	        #endif
151	        #if defined(BENNY_UV) && defined(BENNY05)
152	        gl_FragColor = vec4(vB05Uv, uMaskCol.r, vLayer); // QA bake pass (benny05.ts): uv, part id, shell layer
153	        #endif`,
154	      );
155	    shader.fragmentShader = shader.fragmentShader.replace('uniform vec3 uTip;', 'uniform vec3 uTip; uniform vec3 uMaskCol;');
156	  };
157	  material.customProgramCacheKey = () =>
158	    `benny-fur-${shells}${material.defines?.BENNY_MASK !== undefined ? '-mask' : ''}` +
159	    `${material.defines?.BENNY05 !== undefined ? '-b05' : ''}${material.defines?.BENNY_UV !== undefined ? '-uv' : ''}`;
160	
161	  const mesh = new THREE.InstancedMesh(src.geometry, material, shells);
162	  const I = new THREE.Matrix4();
163	  for (let i = 0; i < shells; i++) mesh.setMatrixAt(i, I);
164	  mesh.instanceMatrix.needsUpdate = true;
165	  mesh.name = src.name;
166	  mesh.position.copy(src.position);
167	  mesh.quaternion.copy(src.quaternion);
168	  mesh.scale.copy(src.scale);
169	  mesh.frustumCulled = false;
170	  return { mesh, material, uniforms };
171	}
