1	#!/usr/bin/env node
2	// benny-character-artist QA probe: load the real game once, goto(05), then for each step file evaluate its JS
3	// (an async function body with `R` = window.__rainbow, `Q` = R.qa3d()) and optionally screenshot.
4	//   node bennyprobe.mjs --q='<query>' --out=DIR step1.js [step2.js ...]   (a step whose name ends in .shot.js screenshots)
5	import { writeFileSync, readFileSync, mkdirSync } from 'node:fs';
6	import { basename } from 'node:path';
7	import { loadPlaywright, CHROMIUM_ARGS, startVite } from '../../../../../scripts/lib/pw.mjs';
8	const args = process.argv.slice(2);
9	const opt = Object.fromEntries(args.filter((a) => a.startsWith('--')).map((a) => { const [k, ...r] = a.slice(2).split('='); return [k, r.join('=')]; }));
10	const steps = args.filter((a) => !a.startsWith('--'));
11	const out = opt.out || 'qa/pilot05/full_reference_match/benny/work/probe';
12	mkdirSync(out, { recursive: true });
13	const { chromium } = loadPlaywright();
14	const vite = await startVite(5231);
15	const browser = await chromium.launch({ args: CHROMIUM_ARGS });
16	const t0 = Date.now();
17	try {
18	  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
19	  page.on('console', (m) => { if (m.type() === 'error' || m.text().startsWith('[benny')) console.log('console:', m.text()); });
20	  page.on('pageerror', (e) => console.log('pageerror', e.message));
21	  await page.goto(`${vite.url}/?qa=1&dpr=1${opt.q ? '&' + opt.q : ''}`);
22	  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 240000 });
23	  console.log('loaded', (Date.now() - t0) / 1000);
24	  await page.evaluate(() => window.__rainbow.goto('05'));
25	  await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => r())));
26	  await page.waitForTimeout(250);
27	  for (const s of steps) {
28	    const body = readFileSync(s, 'utf8');
29	    const res = await page.evaluate(async (b) => { const R = window.__rainbow, Q = R.qa3d(); const f = new Function('R', 'Q', `return (async () => { ${b} })()`); return await f(R, Q); }, body);
30	    if (res && res.saveAs && res.b64) { writeFileSync(`${out}/${res.saveAs}`, Buffer.from(res.b64, 'base64')); delete res.b64; }
31	    console.log(basename(s), JSON.stringify(res));
32	    if (s.endsWith('.shot.js')) {
33	      await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => r())));
34	      await page.waitForTimeout(200);
35	      await page.screenshot({ path: `${out}/${basename(s, '.shot.js')}.png` });
36	    }
37	  }
38	} finally {
39	  await browser.close();
40	  await vite.close();
41	  console.log('done', (Date.now() - t0) / 1000);
42	}
