14	import type { BennyRuntime } from '../types';
15	
16	declare global { interface Window { __done?: boolean; __error?: string; __info?: unknown } }
17	
18	const q = new URLSearchParams(location.search);
19	const furQuality = q.get('quality') === 'low' ? 'low' : 'high';
20	// shape A/B: `&dims={"flat":0.6,"stretch":0.05}` overrides BENNY_DIMS before the procedural build (src=build only)
21	if (q.get('dims')) Object.assign(BENNY_DIMS, JSON.parse(q.get('dims')!));
22	
23	async function make(): Promise<BennyRuntime> {
24	  if (q.get('src') === 'glb') return loadBenny({ furQuality });
25	  const b = buildBenny();
26	  return createBennyRuntime(b.scene, b.animations, { furQuality });
27	}
28	
29	interface Panel {
30	  name: string;
31	  yaw: number;
32	  pitch: number;
33	  dist: number;
34	  expr: string;
35	  swim: number;
36	  fov: number;
37	  tumble: boolean;
38	  /** explicit camera (Benny root at origin, faces +Z); overrides yaw/pitch/dist */
39	  cam?: { pos: [number, number, number]; target: [number, number, number] };
40	}
41	
42	(async () => {
43	  try {
44	    const views = q.get('views') ?? 'refs';
45	    const RIDE = 0.8 * 0.55; // Game.ts: root = water surface + benny.radius * 0.55
46	    const panels: Panel[] =
47	      views === 'refs'
48	        ? [
49	            { name: '05-rear', yaw: Math.PI, pitch: 0.24, dist: 4.4, expr: 'happy', swim: 0.8, fov: 40, tumble: false },
50	            { name: '03-front', yaw: 0.55, pitch: 0.12, dist: 4.2, expr: 'happy', swim: 0.3, fov: 40, tumble: false },
51	            { name: '02-dizzy', yaw: 0.0, pitch: 0.05, dist: 4.2, expr: 'dizzy', swim: 0, fov: 40, tumble: true },
52	          ]
53	        : views === 'measure'
54	          ? // proportion check: rear views at the ride height (lifted) at 12° / 18° / 24° / 28° camera elevation,
55	            // chroma-green background + water so a colour mask separates Benny (qa/pilot05/benny measure script)
56	            // `&elev=12,16,20,24` picks the elevations; `&bennyMask` renders flat ID colours on grey (maskmeasure)
57	            (q.get('elev') ?? '12,18,24,28').split(',').map(Number).map((deg) => ({ name: `rear-${deg}`, yaw: Math.PI, pitch: THREE.MathUtils.degToRad(deg), dist: 7.2, expr: 'happy', swim: 1, fov: 33, tumble: false }))
58	        : views === 'g05'
59	          ? // wave 4: ONE full-size 864×1536 frame with the live stage-05 camera relative to Benny's root, taken
60	            // from qa/capture_log.json, expressed in Benny's own frame (the tube slopes 2.4° down there): root→cam =
61	            // 0.50 to his right, 3.13 up, 6.59 back (25.4° elevation); view pitched 12.7° below his forward axis,
62	            // yawed 2.96° left (STAGE_CAM['05']). `&bennyMask` → flat ID colours on grey for pixel measurement.
63	            [
64	              (() => {
65	                const p = Math.atan2(3.6 + 1.92, 18 + 6.4), y = THREE.MathUtils.degToRad(2.96);
66	                const pos: [number, number, number] = [-0.5, 3.13, -6.585];
67	                const look = [Math.cos(p) * Math.sin(y), -Math.sin(p), Math.cos(p) * Math.cos(y)];
68	                const target: [number, number, number] = [pos[0] + look[0] * 24, pos[1] + look[1] * 24, pos[2] + look[2] * 24];
69	                return { name: 'g05', yaw: 0, pitch: 0, dist: 0, expr: 'happy', swim: 1, fov: 62, tumble: false, cam: { pos, target } };
70	              })(),
71	            ]
72	        : views === 'game'
73	          ? [
74	              // stage 05 ride camera (cameraRig STAGE_CAM['05'])
75	              { name: 'game05', yaw: 0, pitch: 0, dist: 0, expr: 'happy', swim: 1, fov: 62, tumble: false, cam: { pos: [0, 4.1 - RIDE, -6.4], target: [0, 1.8 - RIDE, 18] } },
76	              // reference-like rear camera (ref 05/07/10: ~15–20° above Benny)
77	              { name: 'ref-rear', yaw: Math.PI, pitch: 0.3, dist: 6.0, expr: 'happy', swim: 1, fov: 45, tumble: false },
78	              { name: 'rear-3q', yaw: Math.PI * 0.78, pitch: 0.22, dist: 6.0, expr: 'happy', swim: 1, fov: 45, tumble: false },
79	              { name: 'front', yaw: 0.35, pitch: 0.1, dist: 6.0, expr: 'happy', swim: 0.3, fov: 45, tumble: false },
80	            ]
81	          : [
82	              { name: 'front', yaw: 0, pitch: 0.08, dist: 5.4, expr: 'happy', swim: 0, fov: 35, tumble: false },
83	              { name: '3q', yaw: Math.PI / 4, pitch: 0.08, dist: 5.4, expr: 'happy', swim: 0, fov: 35, tumble: false },
84	              { name: 'side', yaw: -Math.PI / 2, pitch: 0.08, dist: 5.4, expr: 'happy', swim: 0, fov: 35, tumble: false },
85	              { name: 'back', yaw: Math.PI, pitch: 0.08, dist: 5.4, expr: 'happy', swim: 0, fov: 35, tumble: false },
86	              { name: 'rear-high', yaw: Math.PI * 0.92, pitch: 0.5, dist: 5.4, expr: 'happy', swim: 0.8, fov: 35, tumble: false },
87	            ];
88	    if (views === 'cmp') {
89	      // wave 4 identity check, 432×768 each: live 05 rear camera (as g05) · 03-like front ¾ from 30° above WHILE
90	      // riding (ride lean active) · front at rest (lean off) · side at rest · 02 dizzy tumble
91	      const g = (() => {
92	        const p = Math.atan2(3.6 + 1.92, 18 + 6.4), y = THREE.MathUtils.degToRad(2.96);
93	        const pos: [number, number, number] = [-0.5, 3.13, -6.585];
94	        const look = [Math.cos(p) * Math.sin(y), -Math.sin(p), Math.cos(p) * Math.cos(y)];
95	        return { pos, target: [pos[0] + look[0] * 24, pos[1] + look[1] * 24, pos[2] + look[2] * 24] as [number, number, number] };
96	      })();
97	      panels.splice(0, panels.length,
98	        { name: 'g05', yaw: 0, pitch: 0, dist: 0, expr: 'happy', swim: 1, fov: 62, tumble: false, cam: g },
99	        { name: '03-ride', yaw: 0.55, pitch: 0.52, dist: 4.6, expr: 'happy', swim: 1, fov: 40, tumble: false },
100	        { name: 'front', yaw: 0.2, pitch: 0.1, dist: 4.6, expr: 'happy', swim: 0, fov: 40, tumble: false },
101	        { name: 'side', yaw: -Math.PI / 2, pitch: 0.1, dist: 4.6, expr: 'happy', swim: 0, fov: 40, tumble: false },
102	        { name: '02-dizzy', yaw: 0.0, pitch: 0.05, dist: 4.4, expr: 'dizzy', swim: 0, fov: 40, tumble: true },
103	      );
104	    }
105	    const g05 = views === 'g05';
106	    const measure = views === 'measure' || g05;
107	    const PW = g05 ? 864 : views === 'refs' || views === 'game' || views === 'cmp' || measure ? 432 : 360;
108	    const PH = g05 ? 1536 : views === 'refs' || views === 'game' || views === 'cmp' || measure ? 768 : 520;
109	    const W = PW * panels.length, H = PH;
110	    const canvas = document.getElementById('lab') as HTMLCanvasElement;
111	    const renderer = createRenderer(canvas, { preserveDrawingBuffer: true });
112	    renderer.setPixelRatio(1);
113	    renderer.setSize(W, H);
114	    renderer.setScissorTest(true);
115	    const scene = new THREE.Scene();
116	    scene.environment = createCandyEnvironment(renderer);
117	    const maskBg = q.has('bennyMask') ? '#808080' : null;
118	    scene.background = new THREE.Color(maskBg ?? (views === 'turntable' ? '#3a1060' : g05 || views === 'cmp' ? '#29a8e8' : measure ? '#00ff00' : '#c0369c'));
119	    scene.add(new THREE.HemisphereLight('#ffe9ff', '#7a2a9c', 1.1));
120	    const key = new THREE.DirectionalLight('#ffffff', 2.2);
121	    key.position.set(3, 6, 5);
122	    scene.add(key);
123	    const rim = new THREE.DirectionalLight('#9ff6ff', 1.2);
124	    rim.position.set(-4, 2, -5);
125	    scene.add(rim);
126	    // an opaque cyan "water" plane at the game's ride height (refs / game views)
127	    if (views !== 'turntable' && views !== 'cmp') {
128	      const water = new THREE.Mesh(
129	        new THREE.CircleGeometry(40, 64),
130	        measure
131	          ? new THREE.MeshBasicMaterial({ color: maskBg ?? (g05 ? '#2bc4f4' : '#00ff00') })
132	          : new THREE.MeshStandardMaterial({ color: '#29d8ff', roughness: 0.1, metalness: 0.1, emissive: '#0a6f9a', emissiveIntensity: 0.6 }),
133	      );
134	      water.rotation.x = -Math.PI / 2;
135	      // game view: exact game placement (the runtime lifts him while swimming); refs view: lifted ride height
136	      // (measure: the game's real placement, root = water + RIDE; the runtime adds the ride lift itself)
137	      water.position.y = views === 'game' || measure ? -RIDE : -(RIDE + BENNY_RIDE_LIFT);
138	      scene.add(water);
139	    }
140	    let i = 0;
141	    for (const p of panels) {
142	      const b = await make();
143	      b.setExpression(p.expr as 'happy' | 'dizzy' | 'peek');
144	      scene.add(b.root);
145	      for (let t = 0; t < 0.9; t += 1 / 30) b.update(1 / 30, { swim: p.swim, steer: 0, speed: 10, time: t, tumble: p.tumble });
146	      if (p.tumble) b.root.rotation.set(-0.25, 0.15, 0.35);
147	      const cam = new THREE.PerspectiveCamera(p.fov, PW / PH, 0.01, 200);
148	      if (p.cam) {
149	        cam.position.set(...p.cam.pos);
150	        cam.lookAt(new THREE.Vector3(...p.cam.target));
151	      } else {
152	        const target = new THREE.Vector3(0, 0.35, 0);
153	        cam.position.set(Math.sin(p.yaw) * Math.cos(p.pitch) * p.dist, target.y + Math.sin(p.pitch) * p.dist, Math.cos(p.yaw) * Math.cos(p.pitch) * p.dist);
154	        cam.lookAt(target);
155	      }
156	      renderer.setViewport(i * PW, 0, PW, PH);
157	      renderer.setScissor(i * PW, 0, PW, PH);
158	      renderer.render(scene, cam);
159	      scene.remove(b.root);
160	      i++;
161	    }
162	    let tris = 0;
163	    const b = buildBenny();
164	    b.scene.traverse((o) => {
165	      const m = o as THREE.Mesh;
166	      if (m.isMesh) tris += (m.geometry.index ? m.geometry.index.count : m.geometry.attributes.position.count) / 3;
167	    });
168	    window.__info = { baseTriangles: Math.round(tris), furQuality };
169	  } catch (e) {
170	    window.__error = String((e as Error)?.stack ?? e);
171	  }
172	  window.__done = true;
173	})();

